import React from "react";
import { notFound } from "next/navigation";
import { Metadata } from "next";
import { CATEGORIES, getCategoryBySlug } from "@/data/categories";
import { getToolsByCategory } from "@/data/tools";
import { Navbar } from "@/components/navigation/Navbar";
import { Footer } from "@/components/footer/Footer";
import { CategoryPageClient } from "@/components/categories/CategoryPageClient";

interface PageProps {
  params: Promise<{ category: string }>;
}

export async function generateStaticParams() {
  return CATEGORIES.map((cat) => ({
    category: cat.slug,
  }));
}

export async function generateMetadata({ params }: PageProps): Promise<Metadata> {
  const { category: slug } = await params;
  const category = getCategoryBySlug(slug);

  if (!category) {
    return {
      title: "Category Not Found",
    };
  }

  return {
    title: `${category.name} — Free Online Utilities`,
    description: category.description,
    openGraph: {
      title: `${category.name} | Zorli`,
      description: category.description,
    },
  };
}

export default async function CategoryPage({ params }: PageProps) {
  const { category: slug } = await params;
  const category = getCategoryBySlug(slug);

  if (!category) {
    notFound();
  }

  const tools = getToolsByCategory(category.slug);

  return (
    <div className="flex flex-col min-h-screen bg-[#070B24]">
      <Navbar />
      <main className="flex-1 w-full">
        <CategoryPageClient category={category} tools={tools} />
      </main>
      <Footer />
    </div>
  );
}
